function countOfSubstrings(word, k) {
  // Try every start, grow the substring one letter at a time and test it directly.
  let count = 0;
  for (let start = 0; start < word.length; start++) {
    const seen = new Set();
    let consonants = 0;
    for (let end = start; end < word.length; end++) {
      if ('aeiou'.includes(word[end])) seen.add(word[end]);
      else consonants++;
      if (seen.size === 5 && consonants === k) count++;
    }
  }
  return count;
}

