function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 200 + Math.floor(rand() * 51) : 5 + Math.floor(rand() * 10);
  // Small words draw from three consonants so repeats are common; the consonant rate varies from word to word.
  const pool = large ? 'bcdfghjklmnpqrstvwxyz' : 'qxz';
  const rate = 0.05 + rand() * 0.45;
  const letters = [];
  for (let i = 0; i < n; i++) {
    letters.push(rand() < rate ? pool[Math.floor(rand() * pool.length)] : 'aeiou'[Math.floor(rand() * 5)]);
  }
  // Most small words get the five vowels planted at distinct random places, so substrings with every vowel are common.
  if (!large && rand() < 0.75) {
    const spots = Array.from({ length: n }, (_, i) => i);
    for (let i = 0; i < 5; i++) {
      const j = i + Math.floor(rand() * (n - i));
      [spots[i], spots[j]] = [spots[j], spots[i]];
      letters[spots[i]] = 'aeiou'[i];
    }
  }
  // A window with all five vowels holds more consonants when they are common, so k grows with the rate.
  const most = Math.min(n - 5, large ? 2 + Math.floor(40 * rate) : 4);
  return [letters.join(''), Math.floor(rand() * (most + 1))];
}
